package com.digitalbase.ticketing.controller;import com.digitalbase.ticketing.dto.PlanUpgradeRequestDto;import com.digitalbase.ticketing.dto.PlanUpgradeResponseDto;import com.digitalbase.ticketing.dto.PlanUpgradeReviewDto; // 👈 DTO အသစ်ကို Import လုပ်ရန်import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.service.AuthService;import com.digitalbase.ticketing.service.PlanUpgradeService;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.HashMap;import java.util.Map;@RestController@RequestMapping("/api/plan-upgrades")@RequiredArgsConstructorpublic class PlanUpgradeController {    private final PlanUpgradeService planUpgradeService;    private final AuthService authService; // User Object ဆွဲထုတ်ရန်    // =========================================================================    // ၁။ Client ဘက်မှ Plan Upgrade / Renew လုပ်ရန် Request တင်ခြင်း    // =========================================================================    @PostMapping("/request")    @PreAuthorize("hasRole('CLIENT')")    public ResponseEntity<PlanUpgradeResponseDto> requestPlanUpgrade(            @RequestBody PlanUpgradeRequestDto requestDto,            Principal principal) {        User user = authService.getUserByEmail(principal.getName());        PlanUpgradeResponseDto response = planUpgradeService.submitUpgradeRequest(user, requestDto);        return ResponseEntity.ok(response);    }    // =========================================================================    // ၂။ Admin မှ Customer ၏ Request ကို Review (Approve / Reject) လုပ်ခြင်း    // =========================================================================    @PutMapping("/{id}/review")    @PreAuthorize("hasRole('ADMIN')")    public ResponseEntity<Map<String, String>> reviewUpgradeRequest(            @PathVariable("id") Long id,            @RequestBody PlanUpgradeReviewDto reviewDto) {        // Service မှ Message (String) ကို လက်ခံပါမည်        String responseMessage = planUpgradeService.reviewUpgradeRequest(id, reviewDto);        // JSON format အဖြစ် ပြောင်းလဲရန် Map ထဲသို့ ထည့်ပါမည်        Map<String, String> response = new HashMap<>();        response.put("message", responseMessage);        return ResponseEntity.ok(response);    }}